// Robot configuration code.
controller Controller1 = controller(primary);
inertial Inertial7 = inertial(PORT7);

rotation straferot = rotation(PORT4, false);

rotation Driverot = rotation(PORT1, false);

distance DistanceRear = distance(PORT3);
distance leftDistance = distance(PORT4);
distance rightDistance = distance(PORT5);
motor RF = motor(PORT19, ratio6_1, true);

motor RM = motor(PORT20, ratio18_1, true);

motor RB = motor(PORT18, ratio6_1, false);

motor LF = motor(PORT11, ratio6_1, false);

motor LM = motor(PORT14, ratio18_1, false);

