// calibration of sensors
void pre_auton() {
  Inertial7.calibrate();
  //Inertial11.calibrate();
  Driverot.setPosition(0, degrees);
  straferot.setPosition(0, degrees);
  DR4B_A.setPosition(0, degrees);
  DR4B_B.setPosition(0, degrees);
  while (Inertial7.isCalibrating()) {
    wait(50, msec);
  }
  Controller1.rumble(".");  //  notify driver when all sensors calibrated
}

