// PID storage of target variables, and pid values with threshold/precision 
struct PID {
  double kP, kI, kD;
  double error, integral, derivative, prevError;
  double output;

  PID(double p, double i, double d) : kP(p), kI(i), kD(d), error(0), integral(0), derivative(0), prevError(0), output(0) {}
  
  double calculate(double target, double current) {
    error = target - current;
    integral += error;
    derivative = error - prevError;
    prevError = error;

    output = (kP * error) + (kI * integral) + (kD * derivative);
    return output;
  }
};

PID drivePID(3.25, 0, 2.5);
//PID strafePID(3.5, 0, 1);

PID headingPID(1, 0, 1);
PID turnPID(1, 0, 1);


// drivetrain control functions

/*
LVel();
RVel();

LTorque(100);
RTorque(100);
 
LBrake();
RBrake();
*/


void LVel(double vel) {
  LF.spin(forward, vel, percent); 
  LM.spin(forward, vel, percent); 
  LB.spin(forward, vel, percent); 
}
void RVel(double vel) {
  RF.spin(forward, vel, percent); 
  RM.spin(forward, vel, percent); 
  RB.spin(forward, vel, percent); 
}
void DriveVel(double vel) {
  LVel(vel);
  RVel(vel);
}

void LTorque(double tor) {
  LF.setMaxTorque(tor, percent);
  LM.setMaxTorque(tor, percent);
  LB.setMaxTorque(tor, percent);
}
void RTorque(double tor) {
  RF.setMaxTorque(tor, percent);
  RM.setMaxTorque(tor, percent);
  RB.setMaxTorque(tor, percent);
}
void DriveTorque(double tor) {
  LTorque(tor);
  RTorque(tor);
}

void LBrake() {
  LF.setStopping(brake);
  LM.setStopping(brake);
  LB.setStopping(brake);
}
void RBrake() {
  RF.setStopping(brake);
  RM.setStopping(brake);
  RB.setStopping(brake);
}

