void turnTo(double targetHeading, double degrees_tolerence) {  //  simple turning drive function
  while(true) {
    theta = Inertial7.rotation(degrees);
    double headingError = targetHeading - theta; // heading target error

    double turnOut = turnPID.calculate(targetHeading, theta);

    if (turnOut >= 100) {
      turnOut = 100;
    } else if (turnOut <= -100) {
      turnOut = -100;
    };

  
    LTorque(100);
    RTorque(100);

    LVel(turnOut);
    RVel(-turnOut);

    if (fabs(headingError) < (degrees_tolerence)) {
      break;  // break if positions are within thresholds
    }
    vex::this_thread::sleep_for(20);
  }
  LBrake();
  RBrake();
}

void driveDistance(double travel, bool braking, double position_tolerence, double clamp) {  //  drive a stated distance using distance sensors, keeps heading hold
  double targetHeading = theta;
  //printf("\n\n\n\n\n\n\n\n\n\n\n\n driveDistance call ============ \n");  troubleshooting
  while (true) {
      
      //double headingRad = Inertial7.heading() * (M_PI / 180.0);  // Convert to radians

      theta = Inertial7.rotation(degrees);

      double rearDis = DistanceRear.objectDistance(inches);

      

      // --- Errors ---
      double yError = travel - rearDis;
      

      printf("error %.2f\n\n", yError);

      // --- PID Outputs ---
      double drivePIDcalc = drivePID.calculate(travel, rearDis);
      double turnOut = turnPID.calculate(targetHeading, theta);

      printf("drivePIDcalc %.2f\n", drivePIDcalc);

      //clamp for pid output for sin and cos functions to work

      if (drivePIDcalc >= 100) {
        drivePIDcalc = 100;
      } else if (drivePIDcalc <= -100) {
        drivePIDcalc = -100;
      };

      if (turnOut >= 100) {
        turnOut = 100;
      } else if (turnOut <= -100) {
        turnOut = -100;
      };

      if (clamp != 0) {
        if (drivePIDcalc >= clamp) {
        drivePIDcalc = clamp;
        } else if (drivePIDcalc <= -clamp) {
          drivePIDcalc = -clamp;
        };
      }
      double yOut = drivePIDcalc;


      LTorque(100);
      RTorque(100);

      LVel(yOut + turnOut);
      RVel(yOut - turnOut);

      // --- Exit Condition ---
      if (fabs(yError) < position_tolerence) {
        break;  // break if positions are within thresholds
        printf("driveDistance finished \n \n");
      }

      vex::this_thread::sleep_for(20);
    }


    // braking after pid

    // Stop at target if requested
    if (braking) {
      LBrake();
      RBrake();
    }
}

void driveVel(double vel, double drivetime, bool braking) {  //  very simple manual motor movement for when distance sensors arent applicable
  LTorque(100);
  RTorque(100);
  
  LVel(vel);
  RVel(vel);

  wait(drivetime, seconds);

  if (braking) {
    LBrake();
    RBrake();
  }
    
}


double y;  // Forward
double r;  // Rotate

// manual drive function (driver controled)
void ToWheelsDrive() {
  y = Controller1.Axis3.position();  // Forward
  r = Controller1.Axis1.position()*1;  // Rotate          CHANGE STEERING SENSE

  LBrake();
  RBrake();
  
  LTorque(100);
  RTorque(100);

  // Set motor speeds
  LVel(y + r);
  RVel(y - r);
}                               

