    double traveldis = (Driverot.position(degrees)/360)*8.639;
    double travelstrafe = (straferot.position(degrees)/360)*8.639;
    

    // finding difference from previous recording aka distance traveled
    double distance_travelled = traveldis - previous_dis;
    double distance_strafed = travelstrafe - previous_strafe;
    //double amount_turned = Inertial7.heading() - previous_turned;

    // x_pos += distance_travelled * cos(Inertial7.heading() * (M_PI / 180));
