    double theta = Inertial7.rotation() * (M_PI / 180.0);
    double Inertial = Inertial7.rotation();

    double deltaTheta = theta - prevTheta;
    prevTheta = theta;

    double deltaInertial = Inertial - prevInertial;
    prevInertial = Inertial;

    //double corrected_strafe = distance_strafed - (deltaTheta * strafeOffset);
    //double corrected_strafe = distance_strafed - (4*sin(deltaInertial*0.01745)); ///////////////////////////////////////////////////////////////

    // Apply rotation to field coordinates
